            pending_rd_addr <= '0;
        end else begin
            if(decoded_req) pending_rd_addr <= decoded_addr;
        end
    end
    assign rd_mux_addr = decoded_req ? decoded_addr : pending_rd_addr;

    logic readback_err;
    logic readback_done;
    logic [31:0] readback_data;
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_data_var = '0;
        if((rd_mux_addr >= 17'hd000) && (rd_mux_addr <= 17'hd000 + 17'h887)) begin
            readback_data_var = hwif_in.kpv.rd_data;
        end
        if((rd_mux_addr >= 17'he000) && (rd_mux_addr <= 17'he000 + 17'h1ff)) begin
            readback_data_var = hwif_in.kmcsr.rd_data;
        end
        if((rd_mux_addr >= 17'hf000) && (rd_mux_addr <= 17'hf000 + 17'hf)) begin
            readback_data_var = hwif_in.drbg_sampler.rd_data;
        end
        if((rd_mux_addr >= 17'h10000) && (rd_mux_addr <= 17'h10000 + 17'h1b)) begin
            readback_data_var = hwif_in.mailbox_km.rd_data;
        end
        if((rd_mux_addr >= 17'h11000) && (rd_mux_addr <= 17'h11000 + 17'h3ff)) begin
            readback_data_var = hwif_in.otp_efuse_map.rd_data;
        end
        if((rd_mux_addr >= 17'h11400) && (rd_mux_addr <= 17'h11400 + 17'h1b)) begin
            readback_data_var = hwif_in.otp_efuse_ctrl.rd_data;
        end
        if((rd_mux_addr >= 17'h11500) && (rd_mux_addr <= 17'h11500 + 17'h6f)) begin
            readback_data_var = hwif_in.otp_efuse_mmr.rd_data;
        end
        if((rd_mux_addr >= 17'h18000) && (rd_mux_addr <= 17'h18000 + 17'h63)) begin
            readback_data_var = hwif_in.otbn_wrapper_key.rd_data;
        end
        if((rd_mux_addr >= 17'h19000) && (rd_mux_addr <= 17'h19000 + 17'h43)) begin
            readback_data_var = hwif_in.aes_wrapper_key.rd_data;
        end
        if((rd_mux_addr >= 17'h1a000) && (rd_mux_addr <= 17'h1a000 + 17'h43)) begin
            readback_data_var = hwif_in.kmac_wrapper_key.rd_data;
        end
        if((rd_mux_addr >= 17'h1b000) && (rd_mux_addr <= 17'h1b000 + 17'h43)) begin
            readback_data_var = hwif_in.hmac_wrapper_key.rd_data;
        end
        if((rd_mux_addr >= 17'h1c000) && (rd_mux_addr <= 17'h1c000 + 17'h42b)) begin
            readback_data_var = hwif_in.abr_wrapper_key.rd_data;
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr & ~decoded_req_is_external;
        readback_err = '0;
    end

    assign external_rd_ack = readback_external_rd_ack;
    assign cpuif_rd_ack = readback_done | readback_external_rd_ack;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
